definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 30, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/nexus-command.git'
      }
    }

    stage('Docker Preflight') {
      steps {
        sh '''
          docker version
          docker compose version
        '''
      }
    }

    stage('Build + Deploy') {
      steps {
        sh '''
          set -e
          docker compose up -d --build --remove-orphans
        '''
      }
    }

    stage('Status') {
      steps {
        sh 'docker compose ps'
      }
    }
  }

  post {
    success {
      echo 'nexus-command deployed - http://localhost:8721'
    }
    always {
      cleanWs()
    }
  }
}
